    func cancelTransfer(id: String) throws 
    
    func clearFinishedTransfers() 
    
    func closeLinkWindow() 
    
    func currentCode()  -> CodeInfo
    
    func downloadDir()  -> String
    
    /**
     * The 32-byte identity seed, so the platform can move it into the
     * Keychain / Keystore and pass it back via `NodeConfig.identity_seed`.
     */
    func exportIdentitySeed()  -> Data
    
    func identity()  -> DeviceIdentity
    
    /**
     * Feed a peer found by Bonjour (NWBrowser, incl. AWDL) or NsdManager.
     */
    func injectPeer(advert: PeerAdvert) 
    
    func interfaces()  -> [NetInterface]
    
    /**
