     * has opened its link window). Result arrives as `DeviceLinked` / `Error`.
     */
    func linkWithCode(code: String) throws 
    
    /**
     * Allow "Link My Device" requests (authenticated by our code) for a while.
     */
    func openLinkWindow(seconds: UInt32) 
    
    func pauseTransfer(id: String) throws 
    
    func peers()  -> [PeerInfo]
    
    func port()  -> UInt16
    
    func removeInjectedPeer(deviceId: String) 
    
    func respondToOffer(offerId: String, accept: Bool) 
    
    func resumeTransfer(id: String) throws 
    
    func rotateCode() 
    
    func sendClipboard(peerId: String, content: ClipboardContent) throws  -> String
    
    func sendClipboardToCode(code: String, content: ClipboardContent) throws  -> String
    
    /**
     * Starts sending to a discovered or trusted device. Returns the transfer id.
     */
