#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeWarpNode: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = WarpNode

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> WarpNode {
        return WarpNode(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: WarpNode) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WarpNode {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: WarpNode, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeWarpNode_lift(_ pointer: UnsafeMutableRawPointer) throws -> WarpNode {
    return try FfiConverterTypeWarpNode.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeWarpNode_lower(_ value: WarpNode) -> UnsafeMutableRawPointer {
    return FfiConverterTypeWarpNode.lower(value)
}




public struct CodeInfo {
    /**
     * Six digits, no separator.
     */
    public var code: String
    /**
     * `482-910`
     */
    public var display: String
    public var expiresAtMs: UInt64
    /**
     * Payload for the QR code (`warpdrop:` URI with code + direct addresses).
     */
    public var qrPayload: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Six digits, no separator.
         */code: String, 
        /**
         * `482-910`
         */display: String, expiresAtMs: UInt64, 
        /**
         * Payload for the QR code (`warpdrop:` URI with code + direct addresses).
         */qrPayload: String) {
        self.code = code
        self.display = display
        self.expiresAtMs = expiresAtMs
        self.qrPayload = qrPayload
    }
}

