extension CodeInfo: Sendable {}
#endif


extension CodeInfo: Equatable, Hashable {
    public static func ==(lhs: CodeInfo, rhs: CodeInfo) -> Bool {
        if lhs.code != rhs.code {
            return false
        }
        if lhs.display != rhs.display {
            return false
        }
        if lhs.expiresAtMs != rhs.expiresAtMs {
            return false
        }
        if lhs.qrPayload != rhs.qrPayload {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(code)
        hasher.combine(display)
        hasher.combine(expiresAtMs)
        hasher.combine(qrPayload)
    }
}



