         * When the transfer was created (Unix ms) — for stable list ordering.
         */startedAtMs: UInt64, savedPaths: [String]) {
        self.id = id
        self.direction = direction
        self.peerId = peerId
        self.peerName = peerName
        self.title = title
        self.fileCount = fileCount
