    typealias SwiftType = WarpError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WarpError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Io(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Crypto(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Protocol(
            msg: try FfiConverterString.read(from: &buf)
