        case 5: return .PeerNotFound
        case 6: return .InvalidCode
        case 7: return .CodeNotFound
        case 8: return .WrongCode
        case 9: return .Rejected(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Timeout
        case 11: return .Cancelled
        case 12: return .TransferNotFound
        case 13: return .Unreachable(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WarpError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Io(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Crypto(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Protocol(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Config(msg):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(msg, into: &buf)
            
        
        case .PeerNotFound:
            writeInt(&buf, Int32(5))
        
        
        case .InvalidCode:
            writeInt(&buf, Int32(6))
        
        
        case .CodeNotFound:
            writeInt(&buf, Int32(7))
        
        
        case .WrongCode:
            writeInt(&buf, Int32(8))
        
        
        case let .Rejected(reason):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .Timeout:
            writeInt(&buf, Int32(10))
        
        
        case .Cancelled:
            writeInt(&buf, Int32(11))
        
        
        case .TransferNotFound:
            writeInt(&buf, Int32(12))
        
        
        case let .Unreachable(msg):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


