// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * JSON form (desktop webview): `{"type": "transferUpdated", "transfer": {...}}`.
 */

public enum WarpEvent {
    
    case peersChanged(peers: [PeerInfo]
    )
    case codeChanged(code: CodeInfo
    )
    case trustRingChanged(devices: [TrustedDevice]
    )
    case offerReceived(offer: IncomingOffer
    )
    case offerWithdrawn(offerId: String
    )
    case transferUpdated(transfer: TransferSnapshot
    )
    case clipboardReceived(fromDeviceId: String, fromName: String, content: ClipboardContent
    )
    case deviceLinked(device: TrustedDevice
    )
    case error(message: String
    )
}


#if compiler(>=6)
extension WarpEvent: Sendable {}
#endif

