        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .peersChanged(peers: try FfiConverterSequenceTypePeerInfo.read(from: &buf)
        )
        
        case 2: return .codeChanged(code: try FfiConverterTypeCodeInfo.read(from: &buf)
        )
        
        case 3: return .trustRingChanged(devices: try FfiConverterSequenceTypeTrustedDevice.read(from: &buf)
        )
        
        case 4: return .offerReceived(offer: try FfiConverterTypeIncomingOffer.read(from: &buf)
        )
        
        case 5: return .offerWithdrawn(offerId: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .transferUpdated(transfer: try FfiConverterTypeTransferSnapshot.read(from: &buf)
        )
        
        case 7: return .clipboardReceived(fromDeviceId: try FfiConverterString.read(from: &buf), fromName: try FfiConverterString.read(from: &buf), content: try FfiConverterTypeClipboardContent.read(from: &buf)
        )
        
        case 8: return .deviceLinked(device: try FfiConverterTypeTrustedDevice.read(from: &buf)
        )
        
        case 9: return .error(message: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WarpEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .peersChanged(peers):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypePeerInfo.write(peers, into: &buf)
            
        
        case let .codeChanged(code):
            writeInt(&buf, Int32(2))
            FfiConverterTypeCodeInfo.write(code, into: &buf)
            
        
        case let .trustRingChanged(devices):
            writeInt(&buf, Int32(3))
            FfiConverterSequenceTypeTrustedDevice.write(devices, into: &buf)
            
        
        case let .offerReceived(offer):
            writeInt(&buf, Int32(4))
            FfiConverterTypeIncomingOffer.write(offer, into: &buf)
            
        
        case let .offerWithdrawn(offerId):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(offerId, into: &buf)
            
        
        case let .transferUpdated(transfer):
            writeInt(&buf, Int32(6))
            FfiConverterTypeTransferSnapshot.write(transfer, into: &buf)
            
        
        case let .clipboardReceived(fromDeviceId,fromName,content):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(fromDeviceId, into: &buf)
            FfiConverterString.write(fromName, into: &buf)
            FfiConverterTypeClipboardContent.write(content, into: &buf)
            
        
        case let .deviceLinked(device):
            writeInt(&buf, Int32(8))
            FfiConverterTypeTrustedDevice.write(device, into: &buf)
            
        
        case let .error(message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


